import {reveal} from './motion.js';
let active=null;
export function closeHeaderMenus(focus=false){if(!active)return;const old=active;active=null;old.toggle.setAttribute('aria-expanded','false');reveal(old.menu,false);if(focus)old.toggle.focus()}
export function setupHeaderMenus(){
 const position=()=>{if(!active)return;const r=active.toggle.getBoundingClientRect();active.menu.style.left=Math.max(12,Math.min(r.left-125,innerWidth-220))+'px';active.menu.style.top=r.bottom+8+'px'};
 for(const toggle of document.querySelectorAll('[data-nav-toggle]')){const menu=document.getElementById(toggle.getAttribute('aria-controls'));const open=(keyboard=false,last=false)=>{closeHeaderMenus();active={toggle,menu};toggle.setAttribute('aria-expanded','true');position();reveal(menu,true);if(keyboard){const items=menu.querySelectorAll('button');(last?items[items.length-1]:items[0]).focus()}};toggle.onclick=()=>active?.toggle===toggle?closeHeaderMenus():open();toggle.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();open(true,e.key==='ArrowUp')}};
  menu.onkeydown=e=>{const items=[...menu.querySelectorAll('button')],i=items.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();items[e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}if(e.key==='Escape'){e.preventDefault();closeHeaderMenus(true)}};
  menu.onclick=e=>{const button=e.target.closest('[data-nav-action]');if(!button)return;const {navAction:route,target,mode}=button.dataset;closeHeaderMenus();window.dispatchEvent(new CustomEvent('navigate-view',{detail:route}));let tries=0;const jump=()=>{if(document.body.dataset.page!==route&&tries++<40){requestAnimationFrame(jump);return}if(mode){const select=document.querySelector('#calc-mode');select.value=mode;select.dispatchEvent(new Event('change',{bubbles:true}))}const node=document.getElementById(target);node?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'});if(node?.matches('input,textarea,button'))node.focus({preventScroll:true})};requestAnimationFrame(jump)};
 }
 document.addEventListener('pointerdown',e=>{if(active&&!active.menu.contains(e.target)&&!active.toggle.contains(e.target))closeHeaderMenus()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeHeaderMenus(true)});document.addEventListener('focusin',e=>{if(active&&!active.menu.contains(e.target)&&!active.toggle.closest('.nav-group').contains(e.target))closeHeaderMenus()});window.addEventListener('portal-route',()=>closeHeaderMenus());window.addEventListener('resize',()=>closeHeaderMenus());document.addEventListener('scroll',e=>{if(active&&!active.menu.contains(e.target))closeHeaderMenus()},{capture:true,passive:true});
}
